from lib import *
recs=[
R(2034,"Blondie Cranberry",
"Blondie Cranberry adalah camilan manis yang kenyal dengan cranberry kering, keping cokelat putih, dan dilapisi frosting krim keju.",
["3/4 cangkir mentega","1-1/2 cangkir gula merah","2 butir telur besar","1 sendok teh ekstrak vanila","2-1/4 cangkir tepung terigu serbaguna","1-1/2 sendok teh baking powder","1/2 cangkir cranberry kering manis","1/3 cangkir keping cokelat putih","8 ons krim keju","1-1/2 cangkir gula halus","1 sendok teh kayu manis bubuk"],
["Panaskan oven terlebih dahulu hingga 350° F. Lelehkan mentega dalam panci saus dengan api kecil, atau dalam microwave. Aduk bersama gula merah dan biarkan campuran dingin hingga suhu ruang.","Masukkan campuran gula ke dalam mangkuk besar dan kocok bersama telur dan ekstrak vanila.","Campurkan tepung dan baking powder, lalu tambahkan sedikit demi sedikit ke campuran gula. Aduk bersama cokelat putih dan 1/3 cangkir cranberry.","Semprot loyang berukuran 9 x 13 inci dengan semprotan masak. Ratakan adonan di loyang; adonan akan kental. Panggang selama 18 hingga 22 menit. Tusuk gigi yang ditusukkan ke tengah harus keluar dengan sedikit remah saja. Biarkan dingin sepenuhnya.","Biarkan krim keju pada suhu ruang selama sekitar 30 menit. Aduk kayu manis ke dalam gula halus. Kocok dengan mixer tangan selama 1 menit. Mulai tambahkan campuran gula halus sedikit demi sedikit dan kocok hingga halus.","Oleskan frosting pada brownies yang telah dingin. Beri topping sisa cranberry. Potong menjadi 24 bagian. Simpan di lemari es hingga siap disajikan."],
["Cincang cranberry agar tersebar merata di seluruh blondie.","Cranberry mengandung 30 mg kalium per 1/2 cangkir.","Cokelat putih mirip dengan cokelat semi-manis dalam kandungan kalium dan fosfor. Menggunakan jumlah kecil seperti pada resep ini memungkinkan Anda menikmati cokelat sambil tetap ramah ginjal!","Untuk mengurangi karbohidrat menjadi 21 gram per porsi, ganti gula merah dengan campuran gula dan pengganti gula, dan ganti gula halus dengan pengganti gula butiran."],
serving="1 potong"),
R(2035,"Nasi Liar Musim Gugur",
"Nasi Liar Musim Gugur adalah resep lezat dan ramah ginjal yang dapat dinikmati sepanjang tahun.",
["2 sendok makan kismis","1/2 cangkir nasi liar instan, mentah","2 cangkir apel","3/4 cangkir wortel","1/4 cangkir seledri","1/4 cangkir paprika hijau","1/4 sendok teh sage kering utuh","1/4 sendok teh lada hitam","1-1/2 cangkir kaldu ayam rendah natrium","3/4 cangkir beras converted, mentah","1/4 cangkir air perasan lemon segar","1 tangkai sage segar (opsional)"],
["Campurkan kismis dan 1/4 cangkir air panas; diamkan 5 menit. Tiriskan dan sisihkan.","Siapkan nasi liar instan sesuai petunjuk kemasan. Angkat panci dari api dan sisihkan.","Cincang apel, seledri, dan paprika. Serut wortel.","Olesi wajan antilengket besar dengan semprotan masak; letakkan di atas api sedang-besar hingga panas. Masukkan apel, seledri, paprika hijau, dan wortel; tumis hingga renyah namun empuk. Angkat wajan dari api dan sisihkan.","Campurkan 1-1/2 cangkir kaldu ayam rendah natrium, sage, dan lada dalam panci saus besar; didihkan. Aduk beras converted. Tutup, kecilkan api dan didihkan perlahan selama 20 menit atau hingga nasi empuk dan cairan terserap.","Angkat panci dari api; aduk kismis yang disisihkan, nasi liar, campuran apel, dan air perasan 1 buah lemon. Tutup dan diamkan 5 menit.","Pindahkan ke mangkuk saji. Hias dengan tangkai sage segar, jika diinginkan."],
["Bagi sisa nasi menjadi porsi tunggal, masukkan ke dalam kantong freezer kecil dan bekukan. Untuk memanaskannya kembali sebagai makanan cepat saji di lain waktu, microwave selama 1-2 menit atau letakkan kantong freezer dalam panci berisi air mendidih selama beberapa menit.","Jika nasi liar instan tidak tersedia, siapkan nasi liar biasa sebagai berikut: Bilas nasi liar dengan 3 kali pergantian air panas; tiriskan. Campurkan nasi liar dan 1-1/2 cangkir air dalam panci saus sedang. Didihkan; tutup, kecilkan api dan didihkan perlahan selama 50 menit atau hingga nasi empuk dan cairan terserap."],
serving="3/4 cangkir"),
R(2038,"Chorizo Mudah",
"Masakan Barat Daya dari wilayah Arizona memiliki kepribadiannya sendiri yang bersemangat, berdasarkan pengaruh Spanyol dan Meksiko. Chorizo adalah sosis tradisional Spanyol dengan banyak variasi rempah, dan cabai selalu disertakan. Elaine dari Arizona menggunakan keahlian memasaknya dan menciptakan Chorizo Mudah yang ramah ginjal.",
["3 siung bawang putih","1 pon daging sapi giling 85% tanpa lemak","2 sendok makan bubuk cabai pedas","2 sendok makan minyak canola","1 sendok makan paprika","2 sendok teh cuka putih","2 sendok teh cabai merah atau cayenne","1 sendok teh lada hitam","1 sendok teh oregano bubuk"],
["Cincang halus bawang putih.","Dalam mangkuk besar, campurkan semua bahan hingga sangat rata. Masukkan ke dalam wadah kedap udara dan simpan di lemari es 12 hingga 24 jam.","Bagi menjadi porsi 1/4 cangkir atau simpan seluruh resep. Bungkus dengan plastik pembungkus atau kertas daging dan bekukan dalam kantong freezer plastik tebal untuk digunakan nanti.","Saat siap disajikan, masak porsi 1/4 cangkir per orang dalam wajan antilengket atau yang diolesi minyak di atas kompor. Cincang daging menjadi remah halus dengan spatula. Gunakan dalam resep DaVita.com untuk Tortilla Chorizo dan Telur jika diinginkan."],
["Masak seluruh resep sekaligus, jika diinginkan, dan bekukan sisanya untuk digunakan nanti.","Ganti daging sapi dengan daging kalkun giling jika diinginkan. Anda mungkin perlu menambahkan 1 hingga 2 sendok makan minyak.","Ini cara cepat dan lezat untuk meningkatkan asupan protein saat sarapan. Tambahkan 1 atau 2 butir telur atau putih telur.","Tambahkan Chorizo Mudah ke udang atau ayam dengan nasi untuk hidangan satu piring yang pedas."],
serving="1/4 cangkir chorizo"),
R(2039,"Frittata Tahu Kale",
"Tahu mudah digunakan dan merupakan sumber protein sehat jantung yang lebih rendah kalium. Cobalah resep unik ini sebagai pengganti hidangan telur tradisional.",
["1/3 cangkir paprika","1/3 cangkir bawang bombai","2 cangkir kale bayi mentah","2 sendok makan minyak zaitun","1 kotak tahu sutra 12,3 ons","1/3 cangkir tepung buncis (chickpea)","1 sendok makan tepung maizena","1/4 cangkir susu almond tanpa pemanis","1/4 sendok teh bubuk bawang putih","1/4 sendok teh paprika"],
["Cincang paprika dan bawang bombai.","Tumis paprika, bawang bombai, dan kale dengan minyak zaitun dengan api sedang selama sekitar 5 menit.","Blender tahu, tepung buncis, tepung maizena, susu almond, dan bumbu hingga halus.","Tuang campuran tahu ke atas sayuran dalam wajan dan tutup selama 5-10 menit.","Buka tutup, balik dan masak selama sekitar 10 menit. Jika sulit membaliknya, cukup aduk dan masak seperti telur orak-arik."],
["Pastikan menggunakan tahu sutra, bukan tahu biasa, untuk resep ini. Tahu sutra sebaiknya rendah natrium, tetapi selalu periksa kembali label nutrisinya.","Gunakan wajan antilengket yang bagus. Jika Anda membagi bahan menjadi dua dan menggunakan wajan yang lebih kecil, akan lebih mudah membaliknya.","Sebagai pilihan, gunakan sedikit taburan garam hitam India (Kala Namak) untuk rasa belerang seperti telur."],
serving="1/2 resep"),
R(2040,"Punch Protein Sherbet Limau",
"Mendapatkan protein tambahan tidak bisa lebih baik daripada cita rasa Punch Protein Sherbet Limau karya ahli diet ginjal DaVita, Elise dan Brooke. Mereka menciptakan cara mudah bagi pasien dialisis mereka untuk menikmati minuman manis dengan 8 gram protein per porsi.",
["4 cangkir Sprite Zero® (1 liter) atau soda lemon-limau bebas gula lainnya","23 ons jus nanas (1/2 kaleng besar)","1/2 galon sherbet limau","6 sendok takar bubuk protein whey vanila"],
["Lunakkan sherbet beku dalam microwave selama 45 detik hingga 1 menit. Sendokkan ke dalam mangkuk besar.","Tuang Sprite ke atas sherbet dan aduk hingga tercampur rata.","Campurkan bubuk protein whey dan jus nanas dalam blender hingga halus. Tuang ke dalam campuran sherbet dan aduk hingga tercampur rata.","Sajikan segera atau simpan di lemari es. Setelah didinginkan, aduk sebelum disajikan."],
["Ganti Sprite Zero dengan ginger ale atau soda berwarna terang bebas fosfat lainnya. Tambahkan pewarna makanan untuk warna hijau yang lebih cerah.","Ganti dengan rasa sherbet lain jika diinginkan.","Untuk pesta, tambahkan sendok-sendok sherbet yang benar-benar beku terakhir dan biarkan mengapung di atas."],
serving="8 ons"),
R(2042,"Smoothie Vanila",
"Smoothie Vanila adalah suguhan lezat bagi penderita diabetes yang menjalani dialisis. Smoothie ini mengandung putih telur yang bisa menjadi pengganti protein yang bagus. Nikmati resep ramah ginjal ini hari ini.",
["1 sendok makan gula (atau pengganti gula)","1/4 sendok teh ekstrak vanila","8 ons putih telur cair yang dipasteurisasi","3 sendok makan topping kocok"],
["Campurkan semua bahan.","Aduk hingga topping kocok meleleh sepenuhnya"],
["Penderita diabetes dapat mengganti dengan stevia, Equal®, Splenda®, atau pengganti gula lainnya jika diinginkan. Karbohidrat berkurang menjadi 5 gram per porsi jika menggunakan pengganti gula sebagai pengganti gula."],
serving="9 ons"),
R(2043,"Saus Celup Keju Cepat dan Mudah",
"Dari keripik tortilla rendah garam hingga sayuran mentah, Saus Celup Keju Cepat dan Mudah yang ramah ginjal membuat semua orang senang. Kris sedikit memodifikasi resep aslinya, membuatnya sedikit lebih kaya protein dan lebih rendah fosfor dibandingkan banyak saus celup dan olesan lainnya.",
["1-1/2 cangkir keju cottage","1 cangkir krim asam","3 batang daun bawang","2 sendok teh saus pedas Tabasco®","1 sendok teh daun dill","1/2 sendok teh bubuk bawang putih","1/3 cangkir keju biru yang dihancurkan"],
["Blender keju cottage, krim asam, daun bawang, saus pedas, dan bumbu dalam food processor hingga halus.","Tambahkan keju biru dan proses selama beberapa detik.","Hias dengan daun bawang cincang, jika diinginkan."],
["Saus celup ini awet disimpan, yang justru meningkatkan rasa keju dan bawang putih. Jika disimpan lebih dari tiga hari, kurangi keju biru dan bawang putih.","Keju cheddar tajam alami yang tidak diproses dapat menggantikan keju biru. Resep ini membatasi keju biru hingga 1-1/3 sendok teh per porsi.","Rempah lain dapat ditambahkan sesuai selera. Bereksperimenlah!","Saus celup ini lebih rendah fosfor dan lebih tinggi protein dibandingkan banyak resep sejenis.","Padukan dengan biskuit rendah natrium, sayuran mentah, irisan apel, atau tortilla rendah garam."],
serving="3 sendok makan"),
R(2044,"Batang Seledri Hummus dan Paprika Merah",
"Batang Seledri Hummus dan Paprika Merah ini lezat, mudah, dan sehat. Cobalah hidangan pembuka 3 bahan dan 4 langkah ini untuk pesta Anda berikutnya atau sebagai camilan sehat andalan.",
["4 batang seledri (ukuran sedang 8 inci)","2 sendok makan paprika merah","4 sendok makan hummus"],
["Potong ujung batang seledri. Potong paprika merah menjadi potongan persegi 1/4 inci.","Isi setiap batang seledri dengan 1 sendok makan hummus.","Potong setiap batang seledri menjadi 3 bagian","Letakkan 2 potong paprika merah di atas setiap potongan seledri berisi hummus."],
["Variasikan dengan berbagai campuran hummus beraneka rasa.","Masukkan hummus ke dalam kantong plastik, gunting sudutnya, dan semprotkan ke atas batang seledri.","Sebagai pengganti paprika panggang, Anda dapat menggunakan satu toples kecil pimento potong dadu jika lebih disukai."],
serving="3 potong"),
R(2046,"Steak Flank Panggang dengan Pesto Ketumbar",
"Saus pesto lezat yang dibuat dari cabai jalapeno, bawang putih, almond, dan yogurt adalah topping steak yang sempurna. Cobalah Steak Flank Panggang dengan Pesto Ketumbar yang mudah ini saat Anda menyalakan panggangan berikutnya.",
["1/2 buah cabai jalapeno","1 siung bawang putih","1-1/2 sendok makan almond iris","1/2 cangkir yogurt tawar","1/8 sendok teh garam","1/8 sendok teh lada","1 sendok makan air jeruk nipis","1 pon steak flank"],
["Potong dadu cabai jalapeno dan cincang halus bawang putih.","Siapkan pesto dengan mencampurkan almond, yogurt, cabai jalapeno, garam, lada, bawang putih, dan air jeruk nipis dalam blender atau food processor. Blender hingga agak kasar. Sisihkan.","Taburkan garam dan lada pada steak. Panaskan panggangan terlebih dahulu dengan api sedang. Panggang steak hingga tingkat kematangan yang diinginkan atau sekitar 6 menit di setiap sisi. Diamkan selama 5 menit.","Iris steak menjadi irisan tipis. Sajikan dengan 1 sendok makan pesto ketumbar."],
["Sajikan dengan salad kecil dan satu porsi Kentang Goreng Ubi Jalar Tipis dengan Jintan ala Nicole.","Gunakan sisa pesto ketumbar pada sandwich atau sebagai saus celup untuk kentang goreng Nicole."],
serving="3 ons"),
R(2048,"Salad Wortel dan Kembang Kol Panggang",
"Salad Wortel dan Kembang Kol Panggang adalah tambahan yang mengenyangkan untuk hidangan ramah ginjal favorit Anda. Memanggang sayuran meningkatkan rasa, dan dressing yang mudah dibuat serta biji delima memberi sentuhan manis.",
["1 kepala kembang kol kecil","5 buah wortel ukuran sedang","1 buah lobak putih besar","1 buah bawang bombai ukuran sedang","6 sendok makan minyak zaitun","1 sendok makan campuran bumbu Italia","3 sendok makan cuka beras tanpa bumbu","1-1/2 sendok makan sirup maple","1/4 sendok teh mustard kuning","1/4 sendok teh garam","1/4 sendok teh lada hitam","6 cangkir selada daun bayi","1/2 cangkir biji delima"],
["Panaskan oven terlebih dahulu hingga 425° F. Potong kembang kol menjadi kuntum. Kupas wortel, belah dua memanjang, lalu potong menjadi potongan 2 inci. Kupas lobak putih dan potong dadu seukuran gigitan. Potong dadu bawang bombai seukuran gigitan.","Dalam mangkuk besar, aduk kembang kol, wortel, lobak putih, dan bawang bombai dengan 3 sendok makan minyak zaitun dan campuran bumbu Italia. Letakkan di atas loyang dan panggang selama 20 menit. Keluarkan loyang dari oven dan aduk sayuran. Lanjutkan memanggang selama 15 menit atau hingga sayuran empuk.","Selagi sayuran dipanggang, buat dressing salad. Dalam mangkuk kecil, campurkan sisa 3 sendok makan minyak zaitun, cuka beras, sirup maple, mustard, garam, dan lada hitam.","Untuk menyusun salad, campurkan selada dan sayuran panggang, lalu aduk dengan dressing. Beri topping biji delima dan sajikan segera."],
["Jangan menyusun salad hingga siap disajikan.","Beli kuntum kembang kol dan wortel mini agar persiapan lebih cepat."],
serving="1-1/2 cangkir"),
R(2049,"Salad Tahu Tanpa Telur",
"Ini adalah pengganti salad telur yang sangat baik, dengan kolesterol dan lemak jenuh yang lebih sedikit. Mudah dibuat, pilihan hidangan tanpa dimasak.",
["1 kemasan 16 ons Tahu Super Padat","1/4 cangkir bawang merah","1 batang seledri","1 sendok makan dill segar (atau 1 sendok teh dill kering)","1 sendok makan mustard pilihan","5 sendok makan mayones","1/2 sendok teh kunyit untuk warna","Air perasan dari 1/2 buah lemon"],
["Buka kemasan tahu dan peras kelebihan cairan dengan handuk. Cincang bawang merah, seledri, dan dill segar.","Dalam mangkuk besar, tumbuk tahu dengan garpu, penumbuk kentang, atau pemotong adonan.","Dalam mangkuk kecil, campurkan mayones, mustard, dan bumbu.","Letakkan semua bahan di atas tahu tumbuk dalam mangkuk besar dan campurkan. Nikmati seperti salad telur pada umumnya."],
["Pilih tahu super padat polos tanpa bumbu yang tidak dikemas dalam air untuk tekstur yang lebih padat. Tahu lain juga bisa digunakan. Tetapi BUKAN tahu sutra.","Garam hitam (kala namak) adalah pilihan untuk ditambahkan pada resep ini. Mungkin sulit ditemukan di toko, tetapi dapat dipesan secara online. Dianjurkan untuk rasa belerang agar terasa seperti telur.","Dapat ditambahkan sayuran cincang lain seperti paprika atau relish acar (perhatikan natrium). Jika Anda tidak menyukai kunyit atau air perasan lemon, keduanya dapat dihilangkan dari resep.","Anda juga dapat menggunakan mayones vegan sebagai pengganti mayones biasa dalam resep."],
serving="1 cangkir"),
R(2050,"Sup Mi Chik’n",
"Sup Mi Chik’n adalah alternatif nabati yang ramah ginjal untuk sup mi ayam tradisional. Cocok untuk vegetarian atau mereka yang mencari cara menambah protein nabati dalam diet mereka.",
["1-1/2 cangkir kaldu sayuran rendah natrium","1 cangkir air","1/4 sendok teh bumbu unggas","1/4 sendok teh lada hitam","1 cangkir Morningstar Farms® Meal Starters Chik’n Strips vegetarian","1/4 cangkir wortel","2 ons mi telur, mentah"],
["Tuang kaldu sayuran dan air ke dalam slow cooker dengan pengaturan api tinggi.","Bumbui kaldu dengan bumbu unggas, lada, dan garam.","Potong dadu chik’n strips. Potong dadu kecil wortel.","Tambahkan chik’n, wortel, dan mi telur ke dalam sup.","Masak sup dengan pengaturan api tinggi selama 20 hingga 25 menit atau hingga mi matang."],
["Chik’n dan chick’n adalah istilah yang digunakan pada produk pengganti ayam vegetarian. Bahan utamanya adalah protein kedelai. Carilah di bagian freezer toko bahan makanan Anda.","Pilih kaldu rendah natrium yang tidak mencantumkan garam atau kalium klorida dalam daftar bahannya.","Jangan memasak terlalu lama, atau mi akan menjadi lembek."],
serving="1 cangkir"),
R(2051,"Saus Celup Buah Yogurt Creamy",
"Hanya dengan enam bahan, dalam dua langkah cepat Anda dapat membuat saus celup creamy yang menawarkan perpaduan sempurna rasa manis dan asam untuk diet ginjal Anda. Saus celup buah yogurt ini adalah cara ideal untuk menambah lebih banyak buah ke dalam rencana makan Anda sambil tetap mendukung kesehatan ginjal!",
["4 ons krim keju ringan","6 ons yogurt Yunani rendah lemak, rasa vanila","1/4 cangkir Polaner® All Fruit with Fiber Strawberry Spreadable Fruit","1 sendok teh kayu manis","6 sachet pemanis tanpa kalori Splenda®"],
["Campurkan bahan-bahan dengan mixer tangan dalam mangkuk pengaduk sedang hingga halus.","Simpan di lemari es hingga siap disajikan."],
["Sajikan dengan potongan buah rendah kalium pilihan Anda atau biskuit rendah natrium.","Yogurt yang digunakan dalam saus celup ini tidak harus rasa vanila; yogurt tawar juga bisa. Jika Anda menggunakan yogurt rasa lain, kandungan nutrisi dapat berubah, begitu pula warna saus celup. Hal yang sama berlaku jika Anda menggunakan rasa Polaner All Fruit apa pun: rasa dan warna saus celup akan bervariasi.","Saus celup ini mengandung produk susu; dalam jumlah kecil sesuai untuk pasien dialisis jika kalium, fosfor, dan kalsium terkendali dengan baik. Konsultasikan dengan ahli diet ginjal Anda jika perlu dan patuhi porsi yang dianjurkan.","Yogurt Yunani memiliki kandungan protein per porsi yang lebih tinggi dibandingkan yogurt lainnya."],
serving="2 sendok makan"),
R(2052,"Fillet Ikan Panggang dengan Dressing Prancis",
"Ikan adalah pilihan makanan yang sangat sehat, rendah lemak dan sumber nutrisi yang baik, tetapi kita tidak selalu terpikir untuk memasukkannya saat merencanakan menu makan malam. Kini hal itu akan berubah, berkat ahli diet DaVita, Jackie dari North Carolina, dan resep ramah ginjalnya, Fillet Ikan Panggang dengan Dressing Prancis.",
["1 pon fillet ikan putih","1/2 cangkir dressing salad Prancis siap pakai","1/2 cangkir tepung roti panko","1 sendok teh lada hitam"],
["Panaskan oven terlebih dahulu hingga 375° F.","Dalam loyang dangkal yang telah diolesi semprotan masak antilengket, susun fillet ikan.","Bumbui fillet ikan dengan lada hitam.","Lumuri fillet dengan dressing salad Prancis secara merata.","Taburi fillet dengan tepung roti panko.","Panggang selama 20-25 menit atau hingga keemasan dan mudah terpisah menjadi serpihan."],
["Fillet ikan putih meliputi ikan nila, perch, halibut, flounder, dan kod.","Pilih merek dressing salad Prancis dengan kandungan natrium terendah.","Tepung roti biasa dapat digunakan sebagai pengganti panko jika diinginkan.","Jika Anda menjalani diet lebih rendah protein, sesuaikan ukuran porsi dengan rencana makan Anda atau tanyakan kepada ahli diet Anda untuk panduan."],
serving="3 ons fillet matang"),
R(2053,"Nasi Kembang Kol",
"Nasi Kembang Kol adalah hidangan sayuran rendah karbohidrat dan rendah kalori yang sesuai dengan diet ramah ginjal dan ramah diabetes.",
["1 kepala kembang kol kecil","1 sendok makan mentega","1/4 sendok teh lada hitam","1/4 sendok teh bubuk bawang putih","1/4 sendok teh campuran bumbu herba bebas garam"],
["Cuci kembang kol dan potong kuntum dari batangnya.","Pulse potongan kembang kol dalam food processor hingga bertekstur seperti butiran.","Hangatkan mentega dalam panci saus dan tambahkan bumbu.","Masukkan nasi kembang kol dan masak dengan api kecil-sedang selama sekitar 10 menit.","“Gemburkan” dengan garpu dan sajikan."],
["Buat Nasi Kembang Kol Kuning dengan menambahkan sejumput kunyit.","Resep ini bebas gluten."],
serving="3/4 cangkir"),
]
save(5,recs)
